script:
frappe.call({
    method: "frappe.client.get_list",
    args: {
        doctype: "Intercompany Inbox",

        filters: {
            status: ["in", ["Pending", "Accepted", "Rejected"]]
        },

        fields: [
            "name",
            "source_name",
            "target_doctype",
            "status",
            "amount",
            "source_company",
            "target_company",
            "creation"
        ],

        order_by: "creation desc", // latest first
        limit_page_length: 5       // latest 5 documents only
    },

    callback: function (response) {

        if (response.message) {
            populateTaskTable(response.message);
        }
    }
});

function populateTaskTable(tasks) {

    let taskTable = root_element.querySelector("#task_table");

    let tableHTML = `
        <thead>
            <tr>
                <th>Inbox</th>
                <th>Source Document</th>
                <th>Target Doctype</th>
                <th>Status</th>
                <th>Amount</th>
            </tr>
        </thead>
        <tbody>
    `;

    if (tasks.length === 0) {

        tableHTML += `
            <tr>
                <td colspan="5" style="text-align:center;">
                    No Records Found
                </td>
            </tr>
        `;

    } else {

        tasks.forEach(task => {

            let statusColor = "orange";

            if (task.status === "Accepted") {
                statusColor = "green";
            }

            if (task.status === "Rejected") {
                statusColor = "red";
            }

            tableHTML += `
                <tr>

                    <td>
                        <a href="/app/intercompany-inbox/${task.name}">
                            ${task.name}
                        </a>
                    </td>

                    <td>${task.source_name || ""}</td>

                    <td>${task.target_doctype || ""}</td>

                    <td style="color:${statusColor}; font-weight:bold;">
                        ${task.status || ""}
                    </td>

                    <td>${task.amount || 0}</td>

                </tr>
            `;
        });
    }

    tableHTML += `</tbody>`;

    taskTable.innerHTML = tableHTML;
}
